#!/usr/bin/env node
// No compiler dependency: assemble the shared application scope in explicit order.
const fs = require("node:fs");
const path = require("node:path");
const vm = require("node:vm");
const root = path.resolve(__dirname, "..");
const manifest = require("../frontend/build.json");
const check = process.argv.includes("--check");
const banner =
  "Generated by npm run build. Edit frontend/ sources, not this file.";
function assemble(files) {
  return files
    .map(
      (file) =>
        `/* Source: ${file} */\n${fs.readFileSync(path.join(root, file), "utf8").trim()}\n`,
    )
    .join("\n");
}
const guides = Object.fromEntries(
  manifest.guides.map((track) => [
    track,
    JSON.parse(
      fs.readFileSync(
        path.join(root, "frontend/hints", track + ".json"),
        "utf8",
      ),
    ),
  ]),
);
const revisionCatalog = {
  lessons: require("../learning-content/manifest.json").lessons,
  exerciseLinks: require("../learning-content/exercise-links.json"),
};
const outputs = {
  "app.js": `/* ${banner} */\n(function () {\nconst trainingGuides = ${JSON.stringify(guides)};\nconst revisionCatalog = ${JSON.stringify(revisionCatalog)};\n${assemble(manifest.javascript)}\n})();\n`,
  "style.css": `/* ${banner} */\n${assemble(manifest.styles)}`,
};
// Parse before writing, so invalid source cannot replace a working bundle.
new vm.Script(outputs["app.js"], { filename: "app.js" });
let stale = false;
for (const [file, content] of Object.entries(outputs)) {
  const target = path.join(root, file);
  if (check) {
    if (!fs.existsSync(target) || fs.readFileSync(target, "utf8") !== content) {
      console.error(`${file} is stale. Run npm run build.`);
      stale = true;
    }
  } else fs.writeFileSync(target, content);
}
if (stale) process.exitCode = 1;
else
  console.log(
    check
      ? "Frontend bundles match their sources."
      : "Built app.js and style.css.",
  );
